    <script>
        // --- START: THEME SYNC LOGIC ---
        const UNIFIED_THEME_KEY = 'cangxuan_unified_theme';

        function applyTheme(theme) {
            const effectiveTheme = theme === 'dark' ? 'dark' : 'light';
            document.body.setAttribute('data-theme', effectiveTheme);
        }

        function toggleTheme() {
            const currentTheme = document.body.getAttribute('data-theme') || 'light';
            const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
            // Apply theme locally first for instant feedback
            applyTheme(newTheme);
            // Set item in localStorage, which will trigger 'storage' event in other tabs
            localStorage.setItem(UNIFIED_THEME_KEY, newTheme);
        }

        // Listen for theme changes from other tabs
        window.addEventListener('storage', (event) => {
            if (event.key === UNIFIED_THEME_KEY) {
                applyTheme(event.newValue);
            }
        });
        // --- END: THEME SYNC LOGIC ---


        function SafeGetValue(obj, path, defaultValue = "N/A") {
            let keys = Array.isArray(path) ? path : path.split('.');
            let current = obj;
            for (let i = 0; i < keys.length; i++) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                    return defaultValue;
                }
                current = current[keys[i]];
            }
            if (current === undefined || current === null) {
                return defaultValue;
            }
            if (Array.isArray(current)) {
                if (current.length > 0) {
                    const actualValue = current[0];
                    if (typeof actualValue === 'boolean') {
                        return actualValue;
                    }
                    return String(actualValue);
                } else {
                    return defaultValue;
                }
            }
            if (typeof current === 'boolean') {
                return current;
            }
            if (typeof current === 'number') {
                return current;
            }
            if (typeof current === 'string') {
                return current;
            }
            return JSON.stringify(current);
        }

        function updateProgressBar(barId, valueMainId, valueDescId, rawValue, min = 0, max = 100, color) {
            const progressBar = document.getElementById(barId);
            const valueMainDisplay = document.getElementById(valueMainId);
            const valueDescDisplay = document.getElementById(valueDescId);
            if (!progressBar || !valueMainDisplay) {
                return;
            }
            let numericValue = parseFloat(rawValue);
            if (isNaN(numericValue)) {
                numericValue = parseFloat(String(rawValue).replace(/[^0-9.-]/g, ''));
            }
            if (!isNaN(numericValue)) {
                valueMainDisplay.innerText = numericValue;
            } else {
                valueMainDisplay.innerText = rawValue;
            }
            if (valueDescDisplay) {
                valueDescDisplay.innerText = '';
            }
            if (!isNaN(numericValue)) {
                numericValue = Math.max(min, Math.min(max, numericValue));
                const range = max - min;
                const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
                progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
                progressBar.style.backgroundColor = color ? color : '#667eea';
            }
        }

        function toggleSection(sectionId) {
            const content = document.getElementById(`${sectionId}-content`);
            const toggle = document.getElementById(`${sectionId}-toggle`);

            if (content && toggle) {
                content.classList.toggle('collapsed');
                toggle.classList.toggle('collapsed');

                const isCollapsed = content.classList.contains('collapsed');
                localStorage.setItem(`section-${sectionId}`, isCollapsed);
            }
        }

        function getAffectionClass(value) {
            const numValue = parseFloat(value);
            if (numValue >= 90) return 'progress-90-100';
            if (numValue >= 60) return 'progress-60-90';
            if (numValue >= 20) return 'progress-20-60';
            return 'progress-0-20';
        }

        function updateAffectionBar(characterName, value) {
            const progressBar = document.getElementById(`${characterName}Progress`);
            const valueDisplay = document.getElementById(`${characterName}Affection`);

            if (progressBar && valueDisplay) {
                const numValue = parseFloat(value);
                valueDisplay.innerText = numValue;
                progressBar.style.width = `${Math.min(100, Math.max(0, numValue))}%`;
                progressBar.className = `progress-fill ${getAffectionClass(numValue)}`;
            }
        }

        function loadPreferences() {
            // Load and apply the theme on initial page load
            const savedTheme = localStorage.getItem(UNIFIED_THEME_KEY);
            applyTheme(savedTheme); // The default is handled inside applyTheme

            // Load other preferences
            const cultivationCollapsed = localStorage.getItem('section-cultivation') === 'true';
            if (cultivationCollapsed) {
                document.getElementById('cultivation-content').classList.add('collapsed');
                document.getElementById('cultivation-toggle').classList.add('collapsed');
            }

            const companionsCollapsed = localStorage.getItem('section-companions') === 'true';
            if (companionsCollapsed) {
                document.getElementById('companions-content').classList.add('collapsed');
                document.getElementById('companions-toggle').classList.add('collapsed');
            }
        }

        async function initDisplay() {
            try {
                loadPreferences();

                const messages = await getChatMessages(getCurrentMessageId());
                if (!messages || messages.length === 0 || !messages[0].data) {
                    console.error('无法加载消息数据');
                    return;
                }

                const gameData = messages[0].data;
                const characterData = gameData.stat_data;
                if (!characterData) {
                    console.error('无法加载角色数据');
                    return;
                }

                document.getElementById('worldDate').innerText = SafeGetValue(characterData, '世界.日期', '37000-03-15');
                document.getElementById('worldTime').innerText = SafeGetValue(characterData, '世界.时间', '06:00');

                document.getElementById('userRealm').innerText = SafeGetValue(characterData, '{{user}}.境界', '凡人');

                const quotaValue = SafeGetValue(characterData, '{{user}}.双修额度', '可用');
                const quotaElement = document.getElementById('userQuota');
                quotaElement.innerHTML = quotaValue === '可用'
                    ? '<span class="quota-available">可用</span>'
                    : '<span class="quota-used">已用</span>';

                document.getElementById('yuqinghanRealm').innerText = SafeGetValue(characterData, '虞清寒.境界', '合体后期');
                updateAffectionBar('yuqinghan', SafeGetValue(characterData, '虞清寒.倾心值', 0));

                document.getElementById('yinmiaoyanRealm').innerText = SafeGetValue(characterData, '殷妙烟.境界', '合体前期');
                updateAffectionBar('yinmiaoyan', SafeGetValue(characterData, '殷妙烟.倾心值', 0));

                document.getElementById('qinsushuangRealm').innerText = SafeGetValue(characterData, '秦素霜.境界', '化神中期');
                updateAffectionBar('qinsushuang', SafeGetValue(characterData, '秦素霜.倾心值', 5));

                document.getElementById('jiangxiaoliRealm').innerText = SafeGetValue(characterData, '江小鲤.境界', '凡人');
                updateAffectionBar('jiangxiaoli', SafeGetValue(characterData, '江小鲤.倾心值', 10));

                const jadeStatus = SafeGetValue(characterData, '江小鲤.玉佩状态', '遮掩真容');
                document.getElementById('jadeStatus').innerText = jadeStatus;
                const jadeIndicator = document.getElementById('jadeIndicator');
                jadeIndicator.className = jadeStatus === '遮掩真容'
                    ? 'jade-indicator jade-concealed'
                    : 'jade-indicator jade-revealed';

            } catch (error) {
                console.error('初始化显示时出错:', error);
            }
        }

        document.addEventListener('DOMContentLoaded', initDisplay);
    </script>
</body>
</html>
