(async function() {
    const CONFIG = {
        modes: {
            pc: { icon: '💻', name: '电脑插图适配模式', regexes: ["0.[SFW插图]电脑适配", "0.[NSFW插图]电脑适配"] },
            mobile: { icon: '📱', name: '手机插图适配模式', regexes: ["1.[SFW插图]手机适配", "1.[NSFW插图]手机适配"] },
            backup: { icon: '🔧', name: '备用插图适配模式', regexes: ["2.[SFW插图]备用模式", "2.[NSFW插图]备用模式"] }
        },
        delays: {
            switchNotice: 2000,
            reload: 2000,
            updateButtons: 500
        },
        toastTimeout: {
            info: 2000,
            success: 5000,
            error: 3000
        }
    };

    const ALL_REGEX_NAMES = Object.values(CONFIG.modes).flatMap(mode => mode.regexes);

    function getCurrentActiveMode() {
        const regexes = getTavernRegexes({ scope: 'character' });

        for (const [key, mode] of Object.entries(CONFIG.modes)) {
            if (mode.regexes.every(name => 
                regexes.find(r => r.script_name === name && r.enabled)
            )) {
                return key;
            }
        }
        return 'backup';
    }

    async function switchRegexSet(targetMode) {
        if (!CONFIG.modes[targetMode]) {
            throw new Error(`无效的模式: ${targetMode}`);
        }

        try {
            toastr.info('正在切换正则...', '', { timeOut: CONFIG.toastTimeout.info });

            const regexes = getTavernRegexes({ scope: 'character' });
            const targetRegexes = CONFIG.modes[targetMode].regexes;

            regexes.forEach(regex => {
                if (ALL_REGEX_NAMES.includes(regex.script_name)) {
                    regex.enabled = targetRegexes.includes(regex.script_name);
                }
            });

            await replaceTavernRegexes(regexes, { scope: 'character' });

            await reloadChatWithDelay(targetMode);

            updateButtons();

        } catch (error) {
            toastr.error('切换失败: ' + error.message, '', { timeOut: CONFIG.toastTimeout.error });
            console.error('正则切换错误:', error);
        }
    }

    async function reloadChatWithDelay(mode) {
        toastr.info('正在重新加载聊天...', '', { timeOut: CONFIG.toastTimeout.info });

        return new Promise(resolve => {
            setTimeout(async () => {
                if (SillyTavern?.reloadCurrentChat) {
                    await SillyTavern.reloadCurrentChat();
                }

                const modeName = CONFIG.modes[mode].name;
                toastr.success(`已切换到${modeName}并重新加载聊天<br><small>如果嫌太占空间可以去 酒馆助手-脚本库-角色脚本 关闭该脚本</small>`, '', { 
                    timeOut: CONFIG.toastTimeout.success,
                    escapeHtml: false
                });
                resolve();
            }, CONFIG.delays.reload);
        });
    }

    function updateButtons() {
        const currentMode = getCurrentActiveMode();
        const buttons = [];

        Object.entries(CONFIG.modes).forEach(([key, mode]) => {
            if (key !== currentMode) {
                buttons.push({ 
                    name: `${mode.icon} ${mode.name}`, 
                    visible: true 
                });
            }
        });

        buttons.push({ 
            name: `当前: ${CONFIG.modes[currentMode].icon}`, 
            visible: true 
        });

        replaceScriptButtons(getScriptId(), buttons);
    }

    function showStatus() {
        const currentMode = getCurrentActiveMode();
        const regexes = getTavernRegexes({ scope: 'character' });

        let statusText = `当前模式: ${CONFIG.modes[currentMode].name}\n\n`;

        Object.entries(CONFIG.modes).forEach(([key, mode]) => {
            statusText += `${mode.name}正则状态:\n`;
            mode.regexes.forEach(name => {
                const regex = regexes.find(r => r.script_name === name);
                const status = regex?.enabled ? '✅ 启用' : '❌ 禁用';
                statusText += `  ${name}: ${status}\n`;
            });
            statusText += '\n';
        });

        alert(statusText);
    }

    function registerEvents() {
        Object.entries(CONFIG.modes).forEach(([key, mode]) => {
            eventOnButton(`${mode.icon} ${mode.name}`, () => switchRegexSet(key));
        });

        eventOnButton(/^当前:/, showStatus);

        eventOn(tavern_events.CHAT_CHANGED, () => {
            setTimeout(updateButtons, CONFIG.delays.updateButtons);
        });
    }

    function init() {
        updateButtons();
        registerEvents();
        console.log('正则切换器已加载');
    }

    init();
})();

